const results = await Promise.allSettled([
tools.exec_command({cmd:"cat release/scanner_report.json release/build/link.txt release/patches/patch_manifest.json release/gc-sections.log",max_output_tokens:12000}),
tools.exec_command({cmd:"cat release/service.map",max_output_tokens:18000}),
tools.exec_command({cmd:"readelf -W -h -d -n -s release/service",max_output_tokens:12000}),
tools.exec_command({cmd:"cat release/versions.lock release/sbom.spdx.json",max_output_tokens:7000})
]); results.forEach((r,i)=>text({i,...r}));

const results = await Promise.allSettled([
tools.exec_command({cmd:"nm -A -C --defined-only release/lib/*.a",max_output_tokens:5000}),
tools.exec_command({cmd:"readelf -W -n -d --dyn-syms -V release/lib/libvaultcrypto.so.1 release/lib/libvhash.so.1",max_output_tokens:6500}),
tools.exec_command({cmd:"objdump -d -j .text -j .plt release/service && objdump -s -j .rodata release/service",max_output_tokens:7000}),
tools.exec_command({cmd:"readelf -W -d --dyn-syms release/plugins/*.so",max_output_tokens:6500})
]); results.forEach((r,i)=>text({i,...r}));

